package io.colorsand.ui

import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.material3.lightColorScheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.runtime.staticCompositionLocalOf
import androidx.compose.ui.graphics.Color
import io.colorsand.core.SandColor

/** A color scheme: the sand colors plus the colors of the screen around them. */
class Palette(
    val name: String,
    /** Display color of each sand color. */
    val sand: (SandColor) -> Color,
    val backgroundTop: Color,
    val backgroundBottom: Color,
    /** Titles and the main button. */
    val accent: Color,
    /** Text on [accent]. */
    val onAccent: Color,
    /** Hints and notices. */
    val highlight: Color,
    /** A finished tube's outline. */
    val done: Color,
    val surface: Color,
    val text: Color,
    val dimText: Color,
    /** True for a light background; picks Material's light scheme. */
    val isLight: Boolean = false,
    /** Tint inside an empty tube. */
    val glass: Color = Color.White.copy(alpha = 0.06f),
    /** A tube's outline when nothing marks it. */
    val glassOutline: Color = Color.White.copy(alpha = 0.55f),
    /** The streak of light down the side of a tube. */
    val glassShine: Color = Color.White.copy(alpha = 0.18f),
    /** The outline of the selected tube. */
    val selected: Color = Color.White,
    /** Dims the board behind cards and dialogs. */
    val scrim: Color = Color.Black.copy(alpha = 0.45f),
)

object Palettes {
    val Classic = Palette(
        name = "Classic",
        sand = { Color(0xFF000000 or it.rgb.toLong()) },
        backgroundTop = Color(0xFF1B1F3B),
        backgroundBottom = Color(0xFF3B2F5C),
        accent = Color(0xFFF4E4C1),
        onAccent = Color(0xFF1B1F3B),
        highlight = Color(0xFFFFD54F),
        done = Color(0xFF9CCC65),
        surface = Color(0xFF2A2F55),
        text = Color.White,
        dimText = Color.White.copy(alpha = 0.7f),
    )

    /** Classic with the saturation taken down: calmer sand on a quieter night sky. */
    val Soft = Palette(
        name = "Soft",
        sand = {
            when (it) {
                SandColor.RED -> Color(0xFFC8574F)
                SandColor.ORANGE -> Color(0xFFD98A3D)
                SandColor.YELLOW -> Color(0xFFE3C55A)
                SandColor.GREEN -> Color(0xFF5E9A5E)
                SandColor.BLUE -> Color(0xFF4F86C6)
                SandColor.PURPLE -> Color(0xFF8A5A9E)
                SandColor.PINK -> Color(0xFFD0698E)
                SandColor.CYAN -> Color(0xFF3AA3AE)
                SandColor.BROWN -> Color(0xFF7A5E52)
                SandColor.LIME -> Color(0xFFAFB45A)
                SandColor.GRAY -> Color(0xFF9A9A9A)
                SandColor.WHITE -> Color(0xFFE8E4DC)
            }
        },
        backgroundTop = Color(0xFF1E2236),
        backgroundBottom = Color(0xFF34304A),
        accent = Color(0xFFEDE3CF),
        onAccent = Color(0xFF1E2236),
        highlight = Color(0xFFE8C766),
        done = Color(0xFF9DBB7A),
        surface = Color(0xFF2C3049),
        text = Color(0xFFF2F0EC),
        dimText = Color(0xFFF2F0EC).copy(alpha = 0.7f),
    )

    /** Pastel sand on warm paper; the glass is drawn dark so it shows on the light background. */
    val Pastel = Palette(
        name = "Pastel",
        sand = {
            when (it) {
                SandColor.RED -> Color(0xFFF4A09C)
                SandColor.ORANGE -> Color(0xFFF8BC88)
                SandColor.YELLOW -> Color(0xFFFCDD84)
                SandColor.GREEN -> Color(0xFF88C98F)
                SandColor.BLUE -> Color(0xFF9CC3EE)
                SandColor.PURPLE -> Color(0xFFC2A3DE)
                SandColor.PINK -> Color(0xFFF5AFCF)
                SandColor.CYAN -> Color(0xFF8FDCDC)
                SandColor.BROWN -> Color(0xFFBC9A82)
                SandColor.LIME -> Color(0xFFCCE68C)
                SandColor.GRAY -> Color(0xFFA9A9B3)
                SandColor.WHITE -> Color(0xFFFFFFFF)
            }
        },
        backgroundTop = Color(0xFFF7ECDF),
        backgroundBottom = Color(0xFFEFD9CB),
        accent = Color(0xFF7A5547),
        onAccent = Color(0xFFFFF8F0),
        highlight = Color(0xFF8F4E00),
        done = Color(0xFF3D7F3A),
        surface = Color(0xFFFFF8F0),
        text = Color(0xFF4A3A35),
        dimText = Color(0xFF4A3A35).copy(alpha = 0.72f),
        isLight = true,
        glass = Color.White.copy(alpha = 0.35f),
        glassOutline = Color(0xFF8C776C),
        glassShine = Color.White.copy(alpha = 0.5f),
        selected = Color(0xFF4A3A35),
        scrim = Color(0xFF4A3A35).copy(alpha = 0.35f),
    )

    val all: List<Palette> = listOf(Classic, Soft, Pastel)

    /** The palette with this [name], or [Classic] for a name we don't know (say, from an older or newer version). */
    fun byName(name: String?): Palette = all.firstOrNull { it.name == name } ?: Classic
}

/** The palette in use. Read it wherever something is drawn in color. */
val LocalPalette = staticCompositionLocalOf { Palettes.Classic }

@Composable
fun ColorSandTheme(palette: Palette, content: @Composable () -> Unit) {
    val colors = if (palette.isLight) {
        lightColorScheme(
            primary = palette.accent,
            onPrimary = palette.onAccent,
            secondary = palette.highlight,
            background = palette.backgroundTop,
            surface = palette.surface,
            onSurface = palette.text,
            outline = palette.glassOutline,
        )
    } else {
        darkColorScheme(
            primary = palette.accent,
            onPrimary = palette.onAccent,
            secondary = palette.highlight,
            background = palette.backgroundTop,
            surface = palette.surface,
            onSurface = palette.text,
        )
    }
    CompositionLocalProvider(LocalPalette provides palette) {
        MaterialTheme(colorScheme = colors, content = content)
    }
}
